    }
    fprintf(stderr, "\nend   dump: %s\n", "y");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int m = 38;
    int n = 42;

    double A[38][42];
    double x[42];
    double y[42];
    double tmp[38];

    init_array(m, n, A, x);

    kernel_atax(A, x, y, tmp);

    print_array(n, y);

    return 0;
}
